def main():
    data = []
    for rid, contract, classification, owner, definitions, chain, actual, expected, coverage, proposal, impact, acceptance in ROWS:
        definitions = definitions.replace('test_lead.rs:426', 'test_lead.rs:194')
        coverage = coverage.replace('branch_result_review_schema_requires_terminal_returned_results', 'branch_catalog_exposes_only_executable_scopes_and_requires_review_handles').replace('compact_branch_catalog_requires_explicit_scope_selection_and_review', 'compact_lead_can_select_a_runtime_scoped_research_branch')
        data.append({'id': rid, 'contract': contract, 'classification': classification, 'canonical_owner': owner, 'definitions_and_callers': definitions, 'consumer_chain': chain, 'basis': 'environment.json + source-before.json + workspace-inventory.json; historical failures separately indexed in historical-run-inventory.json', 'actual_behavior': actual, 'expected_behavior': expected, 'reproduction': 'python reports/p0-2026-10-11/collect.py (existing workspace checks); tests named under existing_coverage. New diagnostic only for I13/I23: probe.rs + false-blocked-probe.json. Other stronger contract counterexamples NOT RUN.', 'existing_coverage': coverage, 'confidence_limits': 'Finite deterministic fixture scope only. Named checks verified against test-results.json. Source-inspected gaps not claimed reproduced bugs; indirect external clients, late effects and independent science remain unqualified.', 'minimal_next_change_proposal_only': proposal, 'cross_component_impact': impact, 'system_acceptance': acceptance})
    save('gap-matrix.json', data)
    lines = ['# P0 gap matrix', '', 'Basis: `source-before.json`, `environment.json`, `test-results.json`. Classifications apply only to the concrete scope stated. Partial existing implementation does not qualify the stronger full invariant. Proposals below were not implemented.', '', '| ID | Classification | Owner / definitions | Actual behavior / expected gap | Existing coverage | Proposed next change / full acceptance |', '| --- | --- | --- | --- | --- | --- |']
    for row in data:
        def clean(t):
            return t.replace('|', '/').replace('\n', ' ')
        values = [row['id']+' '+row['contract'], row['classification'], row['canonical_owner']+'; '+row['definitions_and_callers'], row['actual_behavior']+' Expected: '+row['expected_behavior'], row['existing_coverage'], row['minimal_next_change_proposal_only']+' Acceptance: '+row['system_acceptance']]
        lines.append('| '+ ' | '.join(clean(v) for v in values)+' |')
    (OUT / 'gap-matrix.md').write_text('\n'.join(lines)+'\n', encoding='utf-8')
    print('matrix rows', len(data))


if __name__ == '__main__':
    main()
